        // --- Projection ---
        const projMat = Mat4.perspective(512);

        // --- Rotate all vertices ---
        function rotateVertex(v, angleX, angleY, angleZ) {
            let vx = v[0], vy = v[1], vz = v[2];
            // Rotate X
            let vy1 = vy * Math.cos(angleX) - vz * Math.sin(angleX);
            let vz1 = vy * Math.sin(angleX) + vz * Math.cos(angleX);
            vy = vy1; vz = vz1;
