        // --- Backface culling ---
        function isBackface(v0, v1, v2) {
            // Compute normal via cross product
            const e1 = [v1[0]-v0[0], v1[1]-v0[1], v1[2]-v0[2]];
            const e2 = [v2[0]-v0[0], v2[1]-v0[1], v2[2]-v0[2]];
            // cross(e1, e2)
